using QuanLyDatTour.Models;using QuanLyDatTour.Services;using Microsoft.Extensions.Configuration;using Microsoft.EntityFrameworkCore;using Serilog;using System.Globalization;
namespace QuanLyDatTour;
public class MainForm:Form{readonly string cs;readonly TyGiaService rates;readonly TabControl tabs=new(){Dock=DockStyle.Fill};readonly DataGridView tourGrid=Grid(),khGrid=Grid(),bookGrid=Grid();readonly TextBox tenTour=new(){Width=150},diem=new(){Width=120},searchTour=new(){Width=150},hoTen=new(){Width=150},sdt=new(){Width=120},email=new(){Width=150},searchKH=new(){Width=150},searchBook=new(){Width=150};readonly ComboBox currency=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=90},customer=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=200},tour=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=250};readonly DateTimePicker departure=new(){Format=DateTimePickerFormat.Short};readonly NumericUpDown price=new(){Maximum=1000000000,DecimalPlaces=2},seats=new(){Minimum=1,Maximum=10000,Value=20},people=new(){Minimum=1,Maximum=100,Value=1};readonly Label quote=new(){AutoSize=true,Padding=new Padding(8)},revenue=new(){AutoSize=true};int tourId=0,khId=0;QLDatTourContext Db()=>new(new DbContextOptionsBuilder<QLDatTourContext>().UseSqlServer(cs).Options);
 public MainForm(IConfiguration c){cs=c.GetConnectionString("DefaultConnection")??"";var s=c.GetSection("ExchangeRate").Get<TyGiaSettings>()??new();rates=new TyGiaService(s);Text="Quản lý đặt tour - v1.0.0";Width=1200;Height=800;StartPosition=FormStartPosition.CenterScreen;tabs.TabPages.Add(BuildTour());tabs.TabPages.Add(BuildCustomer());tabs.TabPages.Add(BuildBooking());Controls.Add(tabs);LoadTours();LoadCustomers();LoadBookings();}
 static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};TabPage BuildTour(){var p=new TabPage("Tour");var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=130};foreach(var c in new Control[]{new Label{Text="Tên tour"},tenTour,new Label{Text="Điểm đến"},diem,new Label{Text="Ngoại tệ"},currency,new Label{Text="Giá ngoại tệ"},price,new Label{Text="Khởi hành"},departure,new Label{Text="Số chỗ"},seats})top.Controls.Add(c);currency.Items.AddRange(new object[]{"THB","KRW","JPY","USD","SGD"});currency.SelectedIndex=0;foreach(var (s,a) in new (string,Action)[]{("Thêm",AddTour),("Sửa",EditTour),("Xóa",DeleteTour),("Làm mới",LoadTours)}){var b=new Button{Text=s,AutoSize=true};b.Click+=(_,_)=>a();top.Controls.Add(b);}top.Controls.Add(searchTour);var f=new Button{Text="Tìm"};f.Click+=(_,_)=>LoadTours();top.Controls.Add(f);var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=130};split.Panel1.Controls.Add(top);split.Panel2.Controls.Add(tourGrid);p.Controls.Add(split);tourGrid.SelectionChanged+=(_,_)=>PickTour();return p;}
 TabPage BuildCustomer(){var p=new TabPage("Khách hàng");var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=90};top.Controls.AddRange(new Control[]{new Label{Text="Họ tên"},hoTen,new Label{Text="SĐT"},sdt,new Label{Text="Email"},email});foreach(var (s,a) in new (string,Action)[]{("Thêm",AddCustomer),("Sửa",EditCustomer),("Xóa",DeleteCustomer),("Làm mới",LoadCustomers)}){var b=new Button{Text=s,AutoSize=true};b.Click+=(_,_)=>a();top.Controls.Add(b);}top.Controls.Add(searchKH);var f=new Button{Text="Tìm"};f.Click+=(_,_)=>LoadCustomers();top.Controls.Add(f);var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=90};split.Panel1.Controls.Add(top);split.Panel2.Controls.Add(khGrid);p.Controls.Add(split);khGrid.SelectionChanged+=(_,_)=>PickCustomer();return p;}
 TabPage BuildBooking(){var p=new TabPage("Đặt tour");var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=160};top.Controls.AddRange(new Control[]{new Label{Text="Khách hàng"},customer,new Label{Text="Tour"},tour,new Label{Text="Số người"},people});tour.SelectedIndexChanged+=async(_,_)=>await UpdateQuote();people.ValueChanged+=async(_,_)=>await UpdateQuote();customer.SelectedIndexChanged+=(_,_)=>{};var b=new Button{Text="Đặt tour"};b.Click+=async(_,_)=>await Book();top.Controls.Add(b);top.Controls.Add(quote);var filter=new FlowLayoutPanel{Dock=DockStyle.Top,Height=40};filter.Controls.Add(new Label{Text="Tìm khách/tour"});filter.Controls.Add(searchBook);var find=new Button{Text="Tìm"};find.Click+=(_,_)=>LoadBookings();filter.Controls.Add(find);var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=180};split.Panel1.Controls.Add(bookGrid);split.Panel2.Controls.Add(revenue);p.Controls.Add(split);p.Controls.Add(filter);p.Controls.Add(top);return p;}
 void LoadTours(){try{using var db=Db();var q=db.Tour.AsNoTracking().AsQueryable();if(searchTour.Text.Trim()!="")q=q.Where(x=>x.TenTour.Contains(searchTour.Text)||x.DiemDen.Contains(searchTour.Text));tourGrid.DataSource=q.OrderBy(x=>x.NgayKhoiHanh).ToList();LoadBookingChoices();}catch(Exception ex){Log.Error(ex,"Load tours");MessageBox.Show("Không kết nối được CSDL. Hãy chạy script SQL và kiểm tra appsettings.json.");}}void PickTour(){if(tourGrid.CurrentRow==null)return;try{tourId=Convert.ToInt32(tourGrid.CurrentRow.Cells["MaTour"].Value);tenTour.Text=Convert.ToString(tourGrid.CurrentRow.Cells["TenTour"].Value)??"";diem.Text=Convert.ToString(tourGrid.CurrentRow.Cells["DiemDen"].Value)??"";currency.SelectedItem=Convert.ToString(tourGrid.CurrentRow.Cells["NgoaiTe"].Value);price.Value=Convert.ToDecimal(tourGrid.CurrentRow.Cells["GiaNgoaiTe"].Value);departure.Value=Convert.ToDateTime(tourGrid.CurrentRow.Cells["NgayKhoiHanh"].Value);seats.Value=Math.Clamp(Convert.ToDecimal(tourGrid.CurrentRow.Cells["SoChoToiDa"].Value),1,10000);}catch{}}
 void AddTour(){if(string.IsNullOrWhiteSpace(tenTour.Text)||string.IsNullOrWhiteSpace(diem.Text)||currency.SelectedItem==null)return;try{using var db=Db();db.Tour.Add(new(){TenTour=tenTour.Text.Trim(),DiemDen=diem.Text.Trim(),NgoaiTe=currency.Text,GiaNgoaiTe=price.Value,NgayKhoiHanh=departure.Value.Date,SoChoToiDa=(int)seats.Value});db.SaveChanges();LoadTours();Log.Information("Tour added");}catch(Exception ex){Log.Error(ex,"Add tour");MessageBox.Show("Không thêm được tour.");}}void EditTour(){if(tourId==0)return;try{using var db=Db();var x=db.Tour.Find(tourId);if(x==null)return;x.TenTour=tenTour.Text.Trim();x.DiemDen=diem.Text.Trim();x.NgoaiTe=currency.Text;x.GiaNgoaiTe=price.Value;x.NgayKhoiHanh=departure.Value.Date;x.SoChoToiDa=(int)seats.Value;db.SaveChanges();LoadTours();}catch(Exception ex){Log.Error(ex,"Edit tour");MessageBox.Show("Không sửa được tour.");}}void DeleteTour(){if(tourId==0)return;if(MessageBox.Show("Xóa tour?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;try{using var db=Db();var x=db.Tour.Find(tourId);if(x!=null)db.Remove(x);db.SaveChanges();LoadTours();}catch(Exception ex){Log.Error(ex,"Delete tour");MessageBox.Show("Không xóa được tour đã có đặt chỗ.");}}
 void LoadCustomers(){try{using var db=Db();var q=db.KhachHang.AsNoTracking().AsQueryable();if(searchKH.Text.Trim()!="")q=q.Where(x=>x.HoTen.Contains(searchKH.Text)||(x.SoDienThoai??"").Contains(searchKH.Text));khGrid.DataSource=q.ToList();LoadBookingChoices();}catch(Exception ex){Log.Error(ex,"Load customers");}}void PickCustomer(){if(khGrid.CurrentRow==null)return;try{khId=Convert.ToInt32(khGrid.CurrentRow.Cells["MaKH"].Value);hoTen.Text=Convert.ToString(khGrid.CurrentRow.Cells["HoTen"].Value)??"";sdt.Text=Convert.ToString(khGrid.CurrentRow.Cells["SoDienThoai"].Value)??"";email.Text=Convert.ToString(khGrid.CurrentRow.Cells["Email"].Value)??"";}catch{}}void AddCustomer(){if(string.IsNullOrWhiteSpace(hoTen.Text)){MessageBox.Show("Họ tên không được trống.");return;}try{using var db=Db();db.KhachHang.Add(new(){HoTen=hoTen.Text.Trim(),SoDienThoai=sdt.Text.Trim(),Email=email.Text.Trim()});db.SaveChanges();LoadCustomers();}catch(Exception ex){Log.Error(ex,"Add customer");MessageBox.Show("Không thêm được khách hàng.");}}void EditCustomer(){if(khId==0)return;try{using var db=Db();var x=db.KhachHang.Find(khId);if(x==null)return;x.HoTen=hoTen.Text.Trim();x.SoDienThoai=sdt.Text.Trim();x.Email=email.Text.Trim();db.SaveChanges();LoadCustomers();}catch(Exception ex){Log.Error(ex,"Edit customer");MessageBox.Show("Không sửa được khách hàng.");}}void DeleteCustomer(){if(khId==0)return;if(MessageBox.Show("Xóa khách hàng?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;try{using var db=Db();var x=db.KhachHang.Find(khId);if(x!=null)db.Remove(x);db.SaveChanges();LoadCustomers();}catch(Exception ex){Log.Error(ex,"Delete customer");MessageBox.Show("Không xóa được khách hàng đã đặt tour.");}}
 void LoadBookingChoices(){try{using var db=Db();var selectedC=customer.SelectedValue is int c?c:0;var selectedT=tour.SelectedValue is int t?t:0;customer.DataSource=db.KhachHang.AsNoTracking().OrderBy(x=>x.HoTen).ToList();customer.DisplayMember="HoTen";customer.ValueMember="MaKH";if(selectedC>0)customer.SelectedValue=selectedC;tour.DataSource=db.Tour.AsNoTracking().OrderBy(x=>x.TenTour).ToList();tour.DisplayMember="TenTour";tour.ValueMember="MaTour";if(selectedT>0)tour.SelectedValue=selectedT;}catch{}}async Task UpdateQuote(){if(tour.SelectedValue==null||!int.TryParse(tour.SelectedValue.ToString(),out int tid))return;try{using var db=Db();var x=db.Tour.Find(tid);if(x==null)return;int booked=db.DatTour.Where(d=>d.MaTour==tid).Sum(d=>(int?)d.SoNguoi)??0;int remaining=Math.Max(0,x.SoChoToiDa-booked);people.Maximum=Math.Max(1,remaining);if(people.Value>people.Maximum)people.Value=people.Maximum;decimal rate=await rates.LayTyGiaAsync(x.NgoaiTe);decimal total=x.GiaNgoaiTe*people.Value*rate;quote.Text=$"Giá/người: {x.GiaNgoaiTe:N2} {x.NgoaiTe} | Tỷ giá {x.NgoaiTe}/VND: {rate:N4} | Còn {remaining} chỗ | Tổng: {total:N0} VND";}catch(Exception ex){Log.Error(ex,"Update rate quote");quote.Text="Không lấy được tỷ giá. Kiểm tra mạng hoặc thử lại.";}}async Task Book(){if(customer.SelectedValue==null||tour.SelectedValue==null){MessageBox.Show("Chọn khách hàng và tour.");return;}try{using var db=Db();int tid=Convert.ToInt32(tour.SelectedValue),cid=Convert.ToInt32(customer.SelectedValue);var x=db.Tour.Find(tid);if(x==null)return;int booked=db.DatTour.Where(d=>d.MaTour==tid).Sum(d=>(int?)d.SoNguoi)??0;int remaining=x.SoChoToiDa-booked;if(people.Value>remaining){MessageBox.Show($"Không đủ chỗ. Chỉ còn {remaining} chỗ.");return;}decimal rate=await rates.LayTyGiaAsync(x.NgoaiTe);decimal total=Math.Round(x.GiaNgoaiTe*people.Value*rate,0);db.DatTour.Add(new(){MaKH=cid,MaTour=tid,SoNguoi=(int)people.Value,NgayDat=DateTime.Now,TyGia=rate,TongTienVND=total});db.SaveChanges();Log.Information("Tour booked {TourId}, people {People}, rate {Rate}, total {Total}",tid,people.Value,rate,total);LoadBookings();await UpdateQuote();MessageBox.Show("Đặt tour thành công.");}catch(Exception ex){Log.Error(ex,"Booking failed");MessageBox.Show("Không thể đặt tour hoặc lấy tỷ giá. Kiểm tra kết nối và thử lại.");}}
 void LoadBookings(){try{using var db=Db();var q=db.DatTour.AsNoTracking().Include(x=>x.KhachHang).Include(x=>x.Tour).AsQueryable();if(searchBook.Text.Trim()!="")q=q.Where(x=>x.KhachHang!.HoTen.Contains(searchBook.Text)||x.Tour!.TenTour.Contains(searchBook.Text));var rows=q.OrderByDescending(x=>x.NgayDat).Select(x=>new{x.MaDat,HoTenKhach=x.KhachHang!.HoTen,TenTour=x.Tour!.TenTour,x.SoNguoi,x.TyGia,x.TongTienVND,x.NgayDat,NgayKhoiHanh=x.Tour.NgayKhoiHanh}).ToList();bookGrid.DataSource=rows;revenue.Text=$"Tổng doanh thu các dòng đang hiển thị: {rows.Sum(x=>x.TongTienVND):N0} VND";}catch(Exception ex){Log.Error(ex,"Load bookings");MessageBox.Show("Không tải được danh sách đặt tour.");}}
}